    const char = raw[i];
    if (char === '~') {
      const next = raw[i + 1];
      if (next === '0') {
        result += '~';
        i += 1;
      } else if (next === '1') {
        result += '/';
        i += 1;
      } else {
        throw new PointerError(`invalid escape in pointer token: ~${next ?? ''}`);
      }
    } else {
      result += char;
    }
  }
