import {
  ARRAY_INDEX,
  PointerError,
  cloneJSON,
  formatPointer,
  isJsonData,
  jsonEqual,
  parsePointer,
  resolve,
  typeName,
} from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);

/**
 * Define an own data property, safe even for keys (like `__proto__`) that
 * would otherwise be intercepted by an accessor on `Object.prototype`.
 *
 * @param {object} target the object to modify
 * @param {string} key the property name
 * @param {unknown} value the property value
 */
function setProperty(target, key, value) {
  Object.defineProperty(target, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/**
 * Check that an operation carries the members its `op` requires, before
 * anything runs.
 *
 * @param {unknown} operation the raw operation
 */
function validateOperation(operation) {
  if (typeof operation !== 'object' || operation === null) {
    throw new Error('operation must be an object');
  }
  const { op } = operation;
  if (!OPS.has(op)) {
    throw new Error(`unknown operation: ${op}`);
  }
  if (!('path' in operation)) {
    throw new Error(`${op} requires a path`);
  }
  if ((op === 'add' || op === 'replace' || op === 'test') && !('value' in operation)) {
    throw new Error(`${op} requires a value`);
  }
  if ((op === 'move' || op === 'copy') && !('from' in operation)) {
    throw new Error(`${op} requires a from`);
  }
}

/**
 * Check that a value is JSON data, for values supplied by a patch operation.
 *
 * @param {unknown} value the value to check
 * @returns {unknown} the same value, when it is valid
 */
function checkValue(value) {
  if (!isJsonData(value)) {
    throw new Error('value is not JSON data');
  }
  return value;
}

/**
 * Add (or overwrite) a value at a pointer, inserting before an array index.
 *
 * @param {unknown} root the document to mutate
 * @param {string} path pointer to add at
 * @param {unknown} value the (already cloned) value to insert
 * @returns {unknown} the (possibly new) root
 */
function performAdd(root, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
  const token = tokens[tokens.length - 1];
  const parentPointer = formatPointer(tokens.slice(0, -1));
  const parent = resolve(root, parentPointer);
  const fullPointer = formatPointer(tokens);
  if (Array.isArray(parent)) {
    let index;
    if (token === '-') {
      index = parent.length;
    } else if (ARRAY_INDEX.test(token)) {
      index = Number(token);
      if (index > parent.length) {
        throw new PointerError(`index out of range: ${token} at ${fullPointer}`, fullPointer);
      }
    } else {
      throw new PointerError(`invalid array index: ${token} at ${fullPointer}`, fullPointer);
    }
    parent.splice(index, 0, value);
  } else if (parent !== null && typeof parent === 'object') {
    setProperty(parent, token, value);
  } else {
    throw new PointerError(`cannot index into ${typeName(parent)} at ${fullPointer}`, fullPointer);
  }
  return root;
