 * Replace the value at a pointer, which must already exist.
 *
 * @param {unknown} root the document to mutate
 * @param {string} path pointer to replace
 * @param {unknown} value the (already cloned) replacement value
 * @returns {unknown} the (possibly new) root
 */
function performReplace(root, path, value) {
  const tokens = parsePointer(path);
  if (tokens.length === 0) return value;
