 * Compare the value at a pointer with an expected value.
 *
 * @param {unknown} root the document to check
 * @param {string} path pointer to the value under test
 * @param {unknown} value the expected value
 * @returns {unknown} the root, unchanged
 */
function performTest(root, path, value) {
  const actual = resolve(root, path);
  if (!jsonEqual(actual, value)) {
    throw new Error(`test failed at ${path}`);
  }
