    throw new Error('patch must be an array');
  }
  let root = cloneJSON(document);
  operations.forEach((operation, index) => {
    try {
      root = applyOperation(root, operation);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, index, { cause: error });
      }
      throw new PatchError(error.message, index);
    }
  });
  return root;
}
